(function(global){
'use strict';
function safeURL(value){if(typeof value!=="string"||value.startsWith("//"))return null;try{const u=new URL(value, 'https://portfolio.invalid/');if(u.origin==='https://portfolio.invalid'&&!value.startsWith('//')&&!value.includes('..')&&!value.startsWith('/'))return value;if(u.protocol==='https:')return u.href;}catch{}return null}
function repositoryURL(value){try{const u=new URL(value);if(u.protocol==='https:'&&u.hostname==='github.com'&&/^\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/?$/.test(u.pathname))return u.href}catch{}return null}
function selectRepositories(repos,config){const includes=new Set((config.includeRepositories||[]).map(n=>n.toLowerCase()));let pattern;try{pattern=new RegExp(config.discoverPattern,'i')}catch{pattern=/sap|treasury|lockbox|cash.sweep|finance|payment/i}return repos.filter(r=>!r.private&&!r.fork&&(includes.size?includes.has(r.full_name.toLowerCase())||includes.has(r.name.toLowerCase()):pattern.test([r.name,r.description,...(r.topics||[])].join(' ')))).filter(r=>repositoryURL(r.html_url)).sort((a,b)=>new Date(b.pushed_at||0)-new Date(a.pushed_at||0));}
async function fetchRepositories(config,request=fetch){if(!/^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,37}[a-zA-Z0-9])?$/.test(config.username||''))return {configured:false,repositories:[]};let repos=[];for(let page=1;page<=10;page++){const res=await request(`https://api.github.com/users/${encodeURIComponent(config.username)}/repos?type=owner&sort=pushed&per_page=100&page=${page}`,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error(res.status===403||res.status===429?'GitHub is temporarily limiting requests.':'GitHub projects are temporarily unavailable.');const data=await res.json();if(!Array.isArray(data))throw Error('Unexpected GitHub response');repos.push(...data);if(data.length<100)break;}return {configured:true,repositories:selectRepositories(repos,config)};}
function credentialIsCurrent(c,now=Date.now()){const url=safeURL(c.url);const expires=c.expiresAt?Date.parse(c.expiresAt):NaN;return c.verified===true&&c.revoked!==true&&Boolean(c.issuer)&&Boolean(url?.startsWith('https://www.credly.com/badges/'))&&(c.nonExpiring===true||Number.isFinite(expires)&&expires>now);}
global.PortfolioGitHub={safeURL,repositoryURL,selectRepositories,fetchRepositories,credentialIsCurrent};
})(typeof window==='undefined'?globalThis:window);
